from __future__ import annotations

def loss(a: float, m: float, c: float, x: float) -> float:
    """Evaluate the three-point absolute loss."""
    if not a <= m <= c:
        raise ValueError("require a <= m <= c")
    return abs(x-a) + abs(x-m) + abs(x-c)

if __name__ == "__main__":
    a, m, c = -2.0, 1.0, 5.0
    for x in (-2.0, -1.0, 0.0, 1.0, 2.0, 4.0, 5.0):
        print(f"x={x:4.1f}, L(x)={loss(a,m,c,x):4.1f}")
    assert min((-2.0,-1.0,0.0,1.0,2.0,4.0,5.0), key=lambda x: loss(a,m,c,x)) == m

from __future__ import annotations

def flow(m: float, t: float, x: float) -> float:
    """Evaluate the no-overshoot unit-speed flow."""
    if t < 0:
        raise ValueError("time must be nonnegative")
    return min(m, x+t) if x < m else max(m, x-t)

if __name__ == "__main__":
    m = 1.0
    for x0 in (-2.0, 5.0):
        states = [flow(m, float(t), x0) for t in range(7)]
        print(f"x0={x0:g}: {states}; hitting time={abs(x0-m):g}")
        assert flow(m, abs(x0-m), x0) == m

from __future__ import annotations
from statistics import median


def l1_optimizer(values: tuple[float, float, float]) -> float:
    """Return the unique three-point absolute-loss minimizer."""
    return float(median(values))

if __name__ == "__main__":
    families = [(-2.0, 1.0, 5.0), (-2.0, 1.0, 50.0), (-2.0, 1.0, 5000.0)]
    for values in families:
        print(f"targets={values}, median optimizer={l1_optimizer(values):g}, mean={sum(values)/3:g}")
        assert l1_optimizer(values) == 1.0

