from __future__ import annotations

def evaluate_clipped_flow(median: float, elapsed: float, initial: float) -> float:
    """Evaluate the exact median-seeking flow in constant time."""
    if elapsed < 0:
        raise ValueError("elapsed time must be nonnegative")
    if initial < median:
        return min(median, initial + elapsed)
    return max(median, initial - elapsed)

